    text.append(table(['risk','top %','FLAG allN','FLAG R-known','tail recall n/N','濃縮','>=+2 damage n/N','>=+5 damage n/N','U5 damage n/N','U10 damage n/N','FLAG正mass pp-sum','FLAG負abs mass pp-sum'],ff))
    text.append('q3上位20%はtail 27/73=36.99%を捕捉するが、U10を30/67=44.78%、実現>=+5を23/48=47.92%巻き込む。q5上位20%でも重大tail 11/23=47.83%に対し、実現>=+5は26/48=54.17%。q5事前相対条件の一部を満たしていても、最終資産に重要な大Winnerを保護できたとは言えない。偽risk側Winner混入、NOT_FLAGGED側capture/density、U2/U3も完全表に保存した。')
    metrics=list(csv.DictReader((PUB/'PROBABILITY_METRICS.csv').open()));text+=['## q5/q3/q2/qNEG・5クラス確率指標','すべて同じR-known1016 ID。qは推定riskであり、校正済み確率の保証ではない。calibration fit0。B0は同一過去trainのDirichlet0.5平滑化頻度で、新モデル有効coverageに加えていない。']
    text.append(table(['target','method','Brier','binary log loss','AUROC','AP'],[[r['target'],r['method']]+[f"{float(r[k]):.6f}" if r[k] else 'N/A' for k in ['Brier','binary_log_loss','AUROC','AP']] for r in metrics if r['mask']=='METHOD_COMMON' and r['target']!='5CLASS']))
