    decision={'status':'RD02_DIRECT_DOWNSIDE_COMPLETE_DEVELOPMENT','performance_status':'NO_INCREMENT_UNDER_TESTED_DESIGN','descriptive_secondary_status':['RANKING_SIGNAL_ONLY_NOT_PROBABILITY_READY','DOWNSIDE_WINNER_TRADEOFF'],'integrity':'PASS_SAME_AUTHOR_SEPARATE_IMPLEMENTATION','coverage':'PASS_1039_OF_1039_ALL3_METHODS_ALL8BLOCKS','D_FULL_prediction_screen':False,'D_FULL_selectivity_screen':False,'within_rank':'A_B_C_DESCRIPTIVE_TAIL_ENRICHMENT; S_INCONCLUSIVE_SMALL_N; Winner_preservation_insufficient','D_FULL_added_value_over_PRICE':'pooled_q3_q5_proper_score_improvement; q2_qNEG_multiclass_worse; overall_increment_not_established','added_value_over_B0_RD01':'B0_full_q3_q5_improvement_but_block_screen_failed; RD01_paired_q3_improved_q5_mixed_LATER_ASOF_REFERENCE','winner_preservation':'INSUFFICIENT','probability_ready':False,'reproduction':'PASS_ONE_CAMPAIGN_NO_REFIT_EXACT_BYTES','successful_fit_N':24,'base_attempt_N':25,'preprocessing_fit_N':24,'repair_cycles_N':5,'repair_limit':20,'completed_blocks':list(range(1,9)),'actual_GET_complete_blocks':list(range(1,9)),'selectedNewRank':None,'mainRank':'SAVED_R0','mainRankChanged':False,'mainCapital':'CAPITAL_MAX3_SLOT_RESERVE_V1','mainExit':'SHARP_DROP_FIRST_OBSERVED_EXIT_V0','CapitalReplay':0,'capitalImprovement':'NOT_EVALUATED','freshValidation':'NOT_RUN','firstLayerChanged':False,'additionalPreBuyP1GateActivated':False,'safety':SAFETY,'publication_status':'AWAITING_FINAL_ACTUAL_GET','terminal_status':'COMPLETE_STOP','next_hypothesis':'Separate BUY_INTENT downside persistence from movement-magnitude risk to preserve U10 and realized>=+5 Winners at the same tail-capture budget; design only'}
